/// Returns a mutable reference to the value currently stored in the
/// `SetOnce`, or `None` if the `SetOnce` is empty.
///
/// Since this call borrows the `SetOnce` mutably, it is safe to mutate the
/// value inside the `SetOnce` — the mutable borrow statically guarantees
/// no other references exist.
pub fn get_mut(&mut self) -> Option<&mut T> {
    if self.initialized() {
        // SAFETY: The value is initialized, and `&mut self` guarantees
        // exclusive access to it for the lifetime of the returned reference.
        Some(unsafe { &mut *self.value.with_mut(|ptr| (*ptr).as_mut_ptr()) })
    } else {
        None
    }
}

/// Sets the value of the `SetOnce` to the given value if the `SetOnce` is
/// empty.

#[test]
fn get_mut_empty() {
    let mut once = SetOnce::<String>::new();

    assert!(once.get_mut().is_none());
    assert!(!once.initialized());
    assert!(once.get().is_none());
    assert!(once.into_inner().is_none());
}

#[tokio::test]
async fn get_mut_after_set() {
    let mut once = SetOnce::new();

    assert!(once.get_mut().is_none());
    once.set(String::from("hello")).unwrap();
    once.get_mut().unwrap().push_str(" world");

    assert!(once.initialized());
    assert_eq!(once.get().unwrap(), "hello world");
    assert_eq!(once.wait().await, "hello world");
    assert!(once.set(String::from("replacement")).is_err());
    assert_eq!(once.into_inner().unwrap(), "hello world");
}

#[test]
fn get_mut_preinitialized() {
    let mut once = SetOnce::new_with(Some(String::from("hello")));

    once.get_mut().unwrap().push_str(" world");

    assert!(once.initialized());
    assert_eq!(once.get().unwrap(), "hello world");
    assert_eq!(once.into_inner().unwrap(), "hello world");
}

#[test]
fn get_mut_drop_cell() {
    let counter = DropCounter::new();
    let mut once = SetOnce::new();
    assert!(once.set((String::from("hello"), counter.clone())).is_ok());

    once.get_mut().unwrap().0.push_str(" world");
    assert_eq!(once.get().unwrap().0, "hello world");
    counter.assert_num_drops(0);

    drop(once);
    counter.assert_num_drops(1);
}

#[test]
fn get_mut_into_inner_ownership() {
    let counter = DropCounter::new();
    let mut once = SetOnce::new_with(Some((String::from("hello"), counter.clone())));

    once.get_mut().unwrap().0.push_str(" world");
    counter.assert_num_drops(0);

    let value = once.into_inner().unwrap();
    assert_eq!(value.0, "hello world");
    counter.assert_num_drops(0);

    drop(value);
    counter.assert_num_drops(1);
}

#[test]
fn get_uninit() {
    static ONCE: SetOnce<u32> = SetOnce::const_new();
    let uninit = ONCE.get();
    assert!(uninit.is_none());
}

